DO $shape$
BEGIN
 IF (SELECT count(*) FROM public.lessons l JOIN finlit_academic_map m ON m.lesson_key=l.content_key WHERE l.is_published) <> 24
 OR EXISTS(SELECT 1 FROM public.lessons l JOIN finlit_academic_map m ON m.lesson_key=l.content_key
 WHERE l.revision <> CASE WHEN l.content_key='lesson-2-1' THEN 2 ELSE 1 END
 OR l.structured_content->>'academicAudit' IS NOT NULL
 OR jsonb_array_length(l.structured_content->'checkpoint') IS DISTINCT FROM 3) THEN
 RAISE EXCEPTION 'Academic patch requires the expected 24 original lesson revisions and three checkpoints each'; END IF;
END;
$shape$;
-- Fingerprints are drift checks against the replayed original JSON, not security hashes.
